import React, { useRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { ANNOTATIONS_PADDING_BOTTOM } from './constants.js';
import { HistogramAnnotationsTooltip } from './HistogramAnnotationsTooltip.js';
import { useHistogramAnnotationsTooltip } from './hooks/useHistogramAnnotationsTooltip.js';
import {
  calculateMarkerCoordinate,
  getMarkerWidth,
  handleMarkerPosition,
  isAnnotationTotallyOutOfBounds,
} from './util/get-marker-position.js';
import { TextEllipsis } from '../../../../typography/TextEllipsis.js';
import { AnnotationsAtom } from '../../../core/components/annotations-atoms/AnnotationsAtom.js';
import { MarkerAtom } from '../../../core/components/annotations-atoms/components/MarkerAtom.js';
import { MarkerSymbolWrapper } from '../../../core/components/annotations-atoms/components/MarkerSymbolWrapper.js';
import { TrackAtom } from '../../../core/components/annotations-atoms/components/TrackAtom.js';
import { MarkerInteractionState } from '../../../core/components/annotations-atoms/types/marker.js';
import { ChartGrid } from '../../../core/components/chart-grid/ChartGridRoot.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { WithId } from '../../../core/types/with-id.js';
import { AREAS } from '../../constants/histogram-grid-area-rules.js';
import {
  useAnnotationsHighlightedMarkers,
  useAnnotationsHoveredMarkers,
} from '../../hooks/store/selectors.js';
import { useHistogramAnnotationsConfig } from '../../hooks/useHistogramAnnotationsConfig.js';
import { useHistogramAnnotationsData } from '../../hooks/useHistogramAnnotationsData.js';
import { useHistogramXScale } from '../../hooks/useHistogramXScale.js';
import { HistogramAnnotationsMarkerProps } from '../../types/histogram-annotations.js';

const MARKERS_TRUNCATION = 'middle';

const StyledGridArea = /* @__PURE__ */ styled(ChartGrid.GridArea)`
  padding-bottom: ${ANNOTATIONS_PADDING_BOTTOM}px;
`;
const showMarkerCount = (count: number): string => {
  return count > 9 ? '9+' : count.toString();
};

function defineIndicatorState(
  group: WithId<HistogramAnnotationsMarkerProps>[],
  highlightedMarkersId: string[],
  hoveredMarkersIds: string[],
): MarkerInteractionState {
  if (group.some((marker) => highlightedMarkersId.includes(marker.id))) {
    return 'active';
  }

  if (group.some((marker) => hoveredMarkersIds.includes(marker.id))) {
    return highlightedMarkersId.length > 0 ? 'inactive' : 'hovered';
  }

  return 'default';
}

export const HistogramAnnotationsArea = () => {
  const { xScale } = useHistogramXScale();
  const { showLabels } = useHistogramAnnotationsConfig();
  const { tracks } = useHistogramAnnotationsData();
  const ref = useRef<HTMLDivElement>(null);
  const {
    selectedItem,
    pinned,
    handleMouseMove,
    handleMouseLeave,
    handleClick,
    handleItemHover,
    handleItemLeave,
  } = useHistogramAnnotationsTooltip(ref);
  const { width: trackWidth } = useGridPlotSize();
  const highlightedMarkersId = useAnnotationsHighlightedMarkers();
  const hoveredMarkersIds = useAnnotationsHoveredMarkers();

  return (
    <StyledGridArea gridArea={AREAS.annotations}>
      {({ availableWidth, availableHeight }) => {
        const labelOffset = availableWidth - trackWidth;
        return (
          <>
            <AnnotationsAtom
              width={availableWidth}
              height={availableHeight}
              showLabels={showLabels}
              labelsWidth={labelOffset}
            >
              {tracks.map((track, index) => {
                const {
                  prioritizedMarkers,
                  tooltipMarkers,
                  label: trackLabel,
                  hidden: trackHidden,
                  symbol: trackSymbol,
                } = track;

                return (
                  <TrackAtom
                    key={index}
                    label={trackLabel}
                    hidden={trackHidden}
                  >
                    {prioritizedMarkers.map((groupMarkers, groupIndex) =>
                      groupMarkers.map((groupMarker, markerIndex) => {
                        const { markers } = groupMarker;
                        const {
                          value,
                          title,
                          color,
                          symbol: markerSymbol,
                          hidden,
                        } = markers[0];

                        if (
                          hidden ||
                          isAnnotationTotallyOutOfBounds(value, xScale)
                        ) {
                          return null;
                        }

                        const text =
                          markers.length > 1
                            ? showMarkerCount(markers.length)
                            : title;
                        const symbol = markerSymbol ?? trackSymbol;

                        const markerLabelWidth = getMarkerWidth(
                          text,
                          value,
                          xScale,
                          trackWidth,
                          symbol,
                        );

                        const markerX = calculateMarkerCoordinate(
                          value,
                          xScale,
                          markerLabelWidth,
                        );

                        const { x, labelWidth } = handleMarkerPosition(
                          markerX,
                          markerLabelWidth,
                          trackWidth,
                        );

                        const markerContent =
                          title.length > 2 ? (
                            <>
                              {'\u00A0'}
                              <TextEllipsis truncationMode={MARKERS_TRUNCATION}>
                                {title}
                              </TextEllipsis>
                              {'\u00A0'}
                            </>
                          ) : (
                            title
                          );

                        const state = defineIndicatorState(
                          markers,
                          highlightedMarkersId,
                          hoveredMarkersIds,
                        );

                        return (
                          <MarkerAtom
                            key={markerIndex}
                            x={x}
                            width={labelWidth}
                            color={color ?? Colors.Icon.Primary.Default}
                            content={
                              markers.length > 1 ? (
                                showMarkerCount(markers.length)
                              ) : symbol ? (
                                <MarkerSymbolWrapper>
                                  {symbol}
                                </MarkerSymbolWrapper>
                              ) : (
                                markerContent
                              )
                            }
                            onClick={handleClick}
                            onMouseMove={(event) =>
                              handleMouseMove(
                                event,
                                tooltipMarkers[groupIndex],
                                markerIndex,
                              )
                            }
                            onMouseLeave={() => handleMouseLeave()}
                            interactionState={state}
                          />
                        );
                      }),
                    )}
                  </TrackAtom>
                );
              })}
            </AnnotationsAtom>
            {selectedItem && (
              <HistogramAnnotationsTooltip
                pinned={pinned}
                tooltipRef={ref}
                position={selectedItem.position}
                markersGroup={selectedItem.markers}
                onItemHover={handleItemHover}
                onItemLeave={handleItemLeave}
              />
            )}
          </>
        );
      }}
    </StyledGridArea>
  );
};

HistogramAnnotationsArea['displayName'] = 'HistogramAnnotationsArea';
